fn handler(with_query: bool) -> LoggingHandler {
    LoggingHandler::new(move |opts| async move {
        let exporter = MemoryLogExporter::new();
        Ok(LoggingTarget {
            client: Arc::new(exporter.client(opts)?),
            query: with_query.then(|| Arc::new(exporter.query()) as _),
        })
    })
}

#[tokio::test]
async fn logging_scenarios_pass_against_fakes() {
    let report = ConformanceRunner::new(scenarios_dir(env!("CARGO_MANIFEST_DIR")))
        .capabilities(["query"])
        .handler(handler(true))
        .run()
        .await
        .unwrap();
    report.assert_success();
    assert_eq!(report.passed(), 3, "{report}");
    assert!(report.result("logging.batch").is_some());
    assert!(format!("{:?}", handler(true)).contains("LoggingHandler"));
}

fn scenario(steps: serde_json::Value, batch: Option<serde_json::Value>) -> Scenario {
    let mut v = json!({"id": "logging.edge", "category": "logging", "steps": steps});
    if let Some(b) = batch {
        v["batchOptions"] = b;
    }
    serde_json::from_value(v).unwrap()
}

async fn run(s: Scenario, with_query: bool) -> ScenarioStatus {
    let report = ConformanceRunner::new("unused")
        .handler(handler(with_query))
        .run_scenarios(&[s])
        .await;
    report.results[0].status.clone()
}

#[tokio::test]
async fn handler_edge_cases() {
    let ok = scenario(
        json!([
            {"op": "sendBatch", "args": {"count": 3, "message": "m #{i}", "severity": "warn",
                                         "attributes": {"i": "#{i}", "n": 1}}},
            {"op": "send", "args": {"message": "x", "traceId": "4bf92f3577b34da6a3ce929d0e0e4736",
                                    "spanId": "00f067aa0ba902b7"}},
            {"op": "flush", "args": {"timeoutMs": 5000}},
            {"op": "stats", "expect": {"equals": {"sent": 4}}},
            {"op": "searchUntil", "args": {"query": "m 2", "timeoutMs": 2000},
             "expect": {"count": 1, "stringForm": {"contains": "\"i\":\"2\""}}}
        ]),
        Some(json!({"maxBatchSize": 2, "flushIntervalMs": 50})),
    );
    assert_eq!(run(ok, true).await, ScenarioStatus::Passed);

    let no_query = scenario(
        json!([{"op": "searchUntil", "args": {"query": "x"}, "expect": {"error": "UNSUPPORTED"}}]),
        None,
    );
    assert_eq!(run(no_query, false).await, ScenarioStatus::Passed);

    let bad = [
        json!([{"op": "send", "args": {}, "expect": {"error": "VALIDATION"}}]),
        json!([{"op": "send", "args": {"message": "x", "severity": "loud"}, "expect": {"error": "VALIDATION"}}]),
        json!([{"op": "sendBatch", "args": {"count": 2}, "expect": {"error": "VALIDATION"}}]),
        json!([{"op": "dance", "expect": {"error": "UNSUPPORTED"}}]),
        json!([{"op": "searchUntil", "args": {"query": "never", "minCount": 1, "timeoutMs": 50},
                "expect": {"error": "TIMEOUT"}}]),
    ];
    for steps in bad {
        assert_eq!(
            run(scenario(steps.clone(), None), true).await,
            ScenarioStatus::Passed,
            "{steps}"
        );
    }

    let bad_batch = scenario(json!([]), Some(json!({"nope": 1})));
    assert!(matches!(run(bad_batch, true).await, ScenarioStatus::Failed(m) if m.contains("setup")));
}

#[test]
fn batch_options_parsing() {
    let o = batch_options_from_json(
        BatchOptions::default(),
        Some(&json!({
            "maxQueueSize": 10, "maxBatchSize": 5, "maxBatchBytes": 100, "flushIntervalMs": 20,
            "exportTimeoutMs": 30, "gzip": false, "dropPolicy": "block",
            "maxExportRetries": 4, "retryBackoffMs": 10
        })),
    )
    .unwrap();
    assert_eq!(
        (o.max_queue_size, o.max_batch_size, o.max_batch_bytes),
        (10, 5, 100)
    );
    assert_eq!(o.flush_interval, Duration::from_millis(20));
    assert_eq!(o.export_timeout, Duration::from_millis(30));
    assert!(!o.gzip);
    assert_eq!(o.drop_policy, DropPolicy::Block);
    assert_eq!(
        (o.max_export_retries, o.retry_backoff),
        (4, Duration::from_millis(10))
    );
    for (k, want) in [
        ("drop_newest", DropPolicy::DropNewest),
        ("drop_oldest", DropPolicy::DropOldest),
    ] {
        let o = batch_options_from_json(BatchOptions::default(), Some(&json!({"dropPolicy": k})))
            .unwrap();
        assert_eq!(o.drop_policy, want);
    }
    assert_eq!(
        batch_options_from_json(BatchOptions::default(), None)
            .unwrap()
            .max_batch_size,
        512
    );
    for bad in [
        json!({"maxQueueSize": -1}),
        json!({"gzip": "yes"}),
        json!({"dropPolicy": "never"}),
        json!({"other": 1}),
        json!({"maxExportRetries": 5_000_000_000u64}),
    ] {
        let err = batch_options_from_json(BatchOptions::default(), Some(&bad)).unwrap_err();
        assert_eq!(err.code(), ErrorCode::Config, "{bad}");
    }
    assert!(
        load_scenarios(scenarios_dir(env!("CARGO_MANIFEST_DIR")))
            .unwrap()
            .len()
            >= 3
    );
}
